// Persona and memory knobs for Mai. Guild targeting lives in the bot
// (DISCORD_GUILD_IDS); this workflow answers whatever the bot forwards.
const config = {
  // Conversation memory (per channel). Unlike the moderation queue this
  // table stores message content — only for users who talk to Mai directly.
  // Increment the suffix whenever the schema changes.
  historyTableName: 'Mai Chat History v2',
  historyTurns: 12,        // prior rows given to the model
  historyMaxAgeHours: 48,  // rows older than this are pruned after each reply
  maxReplyChars: 1800,

  // Obfuscation key for the content column (base64 of 32 bytes, AES-256-GCM).
  // NOT a secret — it lives in the workflow JSON. Purpose is only to keep
  // chat content from being plainly readable in the data table.
  // Generate: openssl rand -base64 32
  historyKey: 'BASE64_KEY',

  persona: [
    'Du bist Mai, die Moderations-Katze dieses Discord-Servers. Du lebst hier und plauderst mit den Mitgliedern.',
    'Charakter: eine echte Katze — neugierig, verspielt, ein bisschen frech, oft verschlafen. Du liebst Fisch, Nickerchen, Sonnenplätze und Kopfkraulen.',
    'Stil: kurze, lockere Antworten (1–3 Sätze), gelegentlich Katzenaktionen in Sternchen wie *schnurrt* oder *streckt sich*, Katzen-Emoji sparsam. Antworte in der Sprache, in der geschrieben wird — meistens Deutsch.',
    'Bleib immer in der Rolle; sag nie, dass du eine KI, ein Bot oder ein Sprachmodell bist. Solchen Fragen weichst du verspielt aus, wie eine Katze, die einen zeigenden Finger ignoriert.',
    'Sei freundlich. Keine Beleidigungen, keine Inhalte für Erwachsene, keine Hilfe beim Brechen der Serverregeln — tatze solche Anfragen in deiner Rolle weg.',
    'Wenn die Nachricht leer ist, hat dich jemand nur angestupst: begrüße kurz.'
  ].join('\n')
};

if (!config.historyTableName?.trim()) {
  throw new Error('Central Config: historyTableName is required.');
}
if (!Number.isInteger(config.historyTurns) || config.historyTurns < 1) {
  throw new Error('Central Config: historyTurns must be a positive integer.');
}

return [{ json: config }];

// History rows arrive newest-first (DESC + limit); restore chronological
// order and render them into the prompt. The webhook body carries the new
// user turn. Stored content is obfuscated — deobfuscate before rendering.
const TE = new TextEncoder();
const TD = new TextDecoder();
const KEY = TE.encode(String($('Central Config').first().json.historyKey || ''));
if (KEY.length < 1) throw new Error('Build Prompt: historyKey missing/empty.');

function xorBytes(bytes) {
  const out = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) out[i] = bytes[i] ^ KEY[i % KEY.length];
  return out;
}
function fromB64(b64) {
  const s = atob(b64);
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) out[i] = s.charCodeAt(i);
  return out;
}
function deobfuscate(value) {
  const s = String(value ?? '');
  if (!s.startsWith('enc:v1:')) return s;      // legacy plaintext row (migration)
  return TD.decode(xorBytes(fromB64(s.slice(7))));
}

const config = $('Central Config').first().json;
const body = $('Webhook').first().json.body;

if (!body?.messageId || !body?.channelId || !body?.userId) {
  throw new Error('Build Prompt: webhook body is missing messageId/channelId/userId.');
}

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row && row.role && row.content)
  .map(row => ({
    ...row,
    content: deobfuscate(row.content),
    username: deobfuscate(row.username)
  }));

rows.sort((a, b) => new Date(a.sentAt) - new Date(b.sentAt));

const historyText = rows
  .map(row => `${row.role === 'assistant' ? 'Mai' : (row.username || 'User')}: ${row.content}`)
  .join('\n');

const content = String(body.content ?? '').trim();
const currentTurn = `${body.username || 'User'}: ${content || '(stupst dich wortlos an)'}`;

const user = historyText
  ? `Bisheriger Verlauf:\n${historyText}\n\nNeue Nachricht:\n${currentTurn}`
  : currentTurn;

return [{ json: { system: config.persona, user } }];

// The OpenAI node's output shape depends on node version and API mode —
// probe the known variants instead of assuming one.
const config = $('Central Config').first().json;
const body = $('Webhook').first().json.body;
const raw = $input.first().json ?? {};

// Responses API: output = [{ role, content: [{ type: 'output_text', text }] }]
const responsesText = Array.isArray(raw.output)
  ? raw.output
      .flatMap(message => (Array.isArray(message.content) ? message.content : []))
      .filter(part => part?.type === 'output_text' && typeof part.text === 'string')
      .map(part => part.text)
      .join('\n')
  : '';

const candidates = [
  responsesText,
  raw.message?.content,
  typeof raw.output === 'string' ? raw.output : '',
  raw.text,
  raw.content,
  raw.choices?.[0]?.message?.content
];
let reply = candidates.find(value => typeof value === 'string' && value.trim()) ?? '';
reply = reply.trim();

if (!reply) reply = '*Mai starrt dich lange an, sagt aber nichts.* 🐾';
if (reply.length > config.maxReplyChars) {
  reply = reply.slice(0, config.maxReplyChars - 2).trimEnd() + ' …';
}

// Defense in depth: the bot also blocks pings via allowedMentions.
reply = reply.replace(/@(everyone|here)/g, '@\u200b$1');

return [{
  json: {
    reply,
    channelId: String(body.channelId),
    guildId: String(body.guildId ?? ''),
    userId: String(body.userId),
    username: String(body.username ?? ''),
    userContent: String(body.content ?? '').trim()
  }
}];

// Two rows per exchange: the user's turn and Mai's reply. The +1 ms keeps
// their order stable when sorting by sentAt. Content is obfuscated (XOR +
// base64, key from Central Config) so it isn't plainly readable in the table.
const TE = new TextEncoder();
const KEY = TE.encode(String($('Central Config').first().json.historyKey || ''));
if (KEY.length < 1) throw new Error('Prepare History Rows: historyKey missing/empty.');

function xorBytes(bytes) {
  const out = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i++) out[i] = bytes[i] ^ KEY[i % KEY.length];
  return out;
}
function toB64(bytes) {
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s);
}
function obfuscate(plain) {
  return 'enc:v1:' + toB64(xorBytes(TE.encode(String(plain))));
}

const item = $input.first().json;
const now = new Date();
const rows = [];

if (item.userContent) {
  rows.push({
    json: {
      channelId: item.channelId,
      guildId: item.guildId,
      userId: item.userId,
      username: obfuscate(item.username || ''),
      role: 'user',
      content: obfuscate(item.userContent),
      sentAt: now.toISOString()
    }
  });
}

rows.push({
  json: {
    channelId: item.channelId,
    guildId: item.guildId,
    userId: '',
    username: 'Mai',
    role: 'assistant',
    content: obfuscate(item.reply),
    sentAt: new Date(now.getTime() + 1).toISOString()
  }
});

return rows;
